#!/bin/sh
# Generated by `depot-enclave launchd render` — do not edit (GAP-01, GAP-36).
# Provisions daemon accounts, socket client groups and per-daemon directories.
set -eu
[ "$(id -u)" -eq 0 ] || {
	echo "provision: must run as root" >&2
	exit 1
}
OS=$(uname -s)

say() { echo "provision: $*"; }
die() {
	echo "provision: $*; refusing to continue" >&2
	exit 1
}
dsval() { # Groups|Users name attr -> first value, empty if absent
	dscl . -read "/$1/$2" "$3" 2>/dev/null | awk 'NR == 1 { print $2 }'
}
dsowner() { # Groups|Users attr id -> name of the record holding id
	dscl . -list "/$1" "$2" 2>/dev/null | awk -v id="$3" '$2 == id { print $1; exit }'
}
mkgroup() { # name gid
	if [ "$OS" = Darwin ]; then
		cur=$(dsval Groups "$1" PrimaryGroupID)
		[ -z "$cur" ] || [ "$cur" = "$2" ] || die "group $1 exists with gid $cur, expected $2"
		own=$(dsowner Groups PrimaryGroupID "$2")
		[ -z "$own" ] || [ "$own" = "$1" ] || die "gid $2 already belongs to group $own (wanted $1)"
		if [ -n "$cur" ]; then say "group $1 ($2) present"; else say "create group $1 ($2)"; fi
		dscl . -create "/Groups/$1" PrimaryGroupID "$2"
		dscl . -create "/Groups/$1" RealName "$1"
		dscl . -create "/Groups/$1" Password '*'
	else
		getent group "$1" >/dev/null || groupadd -g "$2" "$1"
	fi
}
mkuser() { # name uid primary-gid
	if [ "$OS" = Darwin ]; then
		cur=$(dsval Users "$1" UniqueID)
		[ -z "$cur" ] || [ "$cur" = "$2" ] || die "user $1 exists with uid $cur, expected $2"
		own=$(dsowner Users UniqueID "$2")
		[ -z "$own" ] || [ "$own" = "$1" ] || die "uid $2 already belongs to user $own (wanted $1)"
		if [ -n "$cur" ]; then say "user $1 ($2) present"; else say "create user $1 ($2)"; fi
		dscl . -create "/Users/$1" UniqueID "$2"
		dscl . -create "/Users/$1" PrimaryGroupID "$3"
		dscl . -create "/Users/$1" RealName "$1"
		dscl . -create "/Users/$1" UserShell /usr/bin/false
		dscl . -create "/Users/$1" NFSHomeDirectory /var/empty
		dscl . -create "/Users/$1" IsHidden 1
		dscl . -create "/Users/$1" Password '*'
	else
		getent passwd "$1" >/dev/null || useradd -r -M -u "$2" -g "$3" -s /usr/sbin/nologin -d /nonexistent "$1"
	fi
}
addmember() { # group user
	if [ "$OS" = Darwin ]; then dseditgroup -o checkmember -m "$2" "$1" >/dev/null 2>&1 || {
		say "add $2 to $1"
		dseditgroup -o edit -a "$2" -t user "$1"
	}; else usermod -a -G "$1" "$2"; fi
}
mkdirp() { # path owner group mode
	mkdir -p "$1"
	chown "$2:$3" "$1"
	chmod "$4" "$1"
}
WHEEL=wheel
[ "$OS" = Darwin ] || WHEEL=root

mkgroup _llmagent 8701
mkuser _llmagent 701 8701
mkgroup _enclavecas 8702
mkuser _enclavecas 702 8702
mkgroup _piivault 8703
mkuser _piivault 703 8703
mkgroup _enclaveifc 8704
mkuser _enclaveifc 704 8704
mkgroup _enclavezk 8705
mkuser _enclavezk 705 8705
mkgroup _enclaveingress 8708
mkuser _enclaveingress 708 8708

mkgroup _enclave_adapter_c 8711
addmember _enclave_adapter_c _enclaveifc
mkgroup _enclave_cas_c 8712
addmember _enclave_cas_c _llmagent
addmember _enclave_cas_c _piivault
addmember _enclave_cas_c _enclaveifc
addmember _enclave_cas_c _enclavezk
mkgroup _enclave_custody_c 8713
addmember _enclave_custody_c _enclavecas
addmember _enclave_custody_c _enclaveifc
addmember _enclave_custody_c _enclavezk
mkgroup _enclave_ifc_c 8714
addmember _enclave_ifc_c _llmagent
addmember _enclave_ifc_c _piivault
addmember _enclave_ifc_c _enclavezk
mkgroup _enclave_zk_c 8715
addmember _enclave_zk_c _llmagent
addmember _enclave_zk_c _enclavecas
addmember _enclave_zk_c _piivault
addmember _enclave_zk_c _enclaveifc
addmember _enclave_ifc_c _enclaveingress
mkgroup _enclave_journal_r 8720
addmember _enclave_journal_r _enclavezk
mkgroup _enclave_sup_c 8716
addmember _enclave_sup_c _enclavecas

mkdirp /var/run/enclave root "$WHEEL" 0755
mkdirp /var/log/enclave root "$WHEEL" 0755
mkdirp /var/db/enclave root "$WHEEL" 0755
mkdirp /var/run/enclave/adapter _llmagent _enclave_adapter_c 2750
mkdirp /var/log/enclave/adapter _llmagent _enclave_journal_r 2750
mkdirp /var/db/enclave/adapter _llmagent _llmagent 0700
mkdirp /var/run/enclave/cas _enclavecas _enclave_cas_c 2750
mkdirp /var/log/enclave/cas _enclavecas _enclave_journal_r 2750
mkdirp /var/db/enclave/cas _enclavecas _enclavecas 0700
mkdirp /var/run/enclave/custody _piivault _enclave_custody_c 2750
mkdirp /var/log/enclave/custody _piivault _enclave_journal_r 2750
mkdirp /var/db/enclave/custody _piivault _piivault 0700
mkdirp /var/run/enclave/ifc _enclaveifc _enclave_ifc_c 2750
mkdirp /var/log/enclave/ifc _enclaveifc _enclave_journal_r 2750
mkdirp /var/db/enclave/ifc _enclaveifc _enclaveifc 0700
mkdirp /var/run/enclave/zk _enclavezk _enclave_zk_c 2750
mkdirp /var/log/enclave/zk _enclavezk _enclave_journal_r 2750
mkdirp /var/db/enclave/zk _enclavezk _enclavezk 0700
mkdirp /var/run/enclave/supervisor root _enclave_sup_c 2750

# Biometric helper socket directory (GAP-14, DEFECT-F-09: root prepares per-console child at login)
mkdirp /var/run/enclave/intent root "$WHEEL" 0755

# Separate OAuth broker parent; root runtime preparation creates the console child.
mkdirp /var/run/enclave/oidc root "$WHEEL" 0755

# CDP Browser sandbox (GAP-34)
mkgroup _cdpbrowser 8707
mkuser _cdpbrowser 707 8707
mkgroup _enclave_browser_c 8718
addmember _enclave_browser_c _llmagent
mkdirp /var/run/enclave/browser _cdpbrowser _enclave_browser_c 2750
mkdirp /var/log/enclave/browser _cdpbrowser _cdpbrowser 0700
mkdirp /var/db/enclave/browser _cdpbrowser _cdpbrowser 0700

# Dedicated authenticated console ingress (F97)
mkdirp /var/run/enclave/gateway _enclaveingress _enclaveingress 0755
mkdirp /var/log/enclave/gateway _enclaveingress _enclaveingress 0700

# Dedicated witness socket channel (GAP-10)
mkgroup _enclave_witness_c 8719
addmember _enclave_witness_c _piivault
mkdirp /var/run/enclave/zk-witness _enclavezk _enclave_witness_c 2750

# Detached hydration jobs directory (FS-706, D-R8)
mkdirp /var/run/enclave/jobs _enclavecas _enclavecas 0700
